package cn.codedog.service;
import java.util.*;import java.time.*;import java.sql.Timestamp;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
@Service public class RankingMonthlyService {
 private final JdbcTemplate j;public RankingMonthlyService(JdbcTemplate j){this.j=j;}
 public Map<String,Object> board(String owner,String month,String student){YearMonth m;try{m=YearMonth.parse(month==null||month.isBlank()?YearMonth.now(ZoneId.of("Asia/Shanghai")).toString():month);if(m.getYear()<2000||m.getYear()>2100)throw new IllegalArgumentException();}catch(Exception e){throw RankingPointsService.conflict("月份格式应为YYYY-MM");}
 Timestamp start=Timestamp.from(m.atDay(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()),end=Timestamp.from(m.plusMonths(1).atDay(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant());
 var rows=j.queryForList("SELECT s.student_id,MAX(s.student_name) student_name,COALESCE(SUM(CASE WHEN l.ended_at>=? AND l.ended_at<? THEN r.total_points ELSE 0 END),0) earned_points FROM ranking_students s LEFT JOIN ranking_lesson_results r ON r.owner_username=s.owner_username AND r.camp_id=s.camp_id AND r.class_id=s.class_id AND r.student_id=s.student_id LEFT JOIN ranking_lessons l ON l.owner_username=r.owner_username AND l.camp_id=r.camp_id AND l.class_id=r.class_id AND l.lesson_id=r.lesson_id WHERE s.owner_username=?"+(student!=null?" AND NOT EXISTS(SELECT 1 FROM ranking_current_ownership o WHERE o.student_id=s.student_id AND (o.state<>'ACTIVE' OR o.owner_username<>s.owner_username))":"")+" GROUP BY s.student_id ORDER BY earned_points DESC,s.student_id",start,end,owner);
 long previous=Long.MIN_VALUE;int rank=0;for(int i=0;i<rows.size();i++){var row=rows.get(i);long score=((Number)row.get("earned_points")).longValue();if(score!=previous)rank=i+1;row.put("rank",rank);previous=score;}
 var visible=student==null?rows:new ArrayList<>(rows.stream().limit(10).toList());if(student!=null&&visible.stream().noneMatch(r->student.equals(r.get("student_id"))))rows.stream().filter(r->student.equals(r.get("student_id"))).findFirst().ifPresent(visible::add);
 Object updated=j.queryForObject("SELECT MAX(t.changed) FROM (SELECT MAX(updated_at) changed FROM ranking_lesson_results WHERE owner_username=? UNION ALL SELECT MAX(updated_at) changed FROM ranking_lessons WHERE owner_username=?) t",Timestamp.class,owner,owner);
 return Map.of("month",m.toString(),"rankings",visible,"missingDateCount",j.queryForObject("SELECT COUNT(*) FROM ranking_lessons WHERE owner_username=? AND ended_at IS NULL",Long.class,owner),"updatedAt",updated==null?"":((Timestamp)updated).toInstant().toString(),"rule","按课程实际月份累计正常获得积分；不含人工调整、兑换、退款与交接");
 }
 public List<Map<String,Object>> dates(String owner){return j.queryForList("SELECT camp_id,class_id,lesson_id,lesson_name,ended_at,updated_at FROM ranking_lessons WHERE owner_username=? ORDER BY camp_id,class_id,lesson_id",owner);}
 public record LessonDate(String campId,String classId,String lessonId,Instant endedAt){}
 @Transactional public Map<String,Object> date(String owner,LessonDate b){if(b.endedAt()==null||b.endedAt().atZone(ZoneId.of("Asia/Shanghai")).getYear()<2000||b.endedAt().isAfter(Instant.now().plusSeconds(86400)))throw RankingPointsService.conflict("请填写可靠的实际课程日期");j.queryForList("SELECT username FROM users WHERE username=? FOR UPDATE",owner);var before=j.queryForList("SELECT ended_at FROM ranking_lessons WHERE owner_username=? AND camp_id=? AND class_id=? AND lesson_id=? FOR UPDATE",owner,b.campId(),b.classId(),b.lessonId());if(before.isEmpty())throw RankingPointsService.conflict("课节不属于当前老师");j.update("UPDATE ranking_lessons SET ended_at=?,updated_at=CURRENT_TIMESTAMP(6) WHERE owner_username=? AND camp_id=? AND class_id=? AND lesson_id=?",Timestamp.from(b.endedAt()),owner,b.campId(),b.classId(),b.lessonId());return Map.of("before",before,"after",b);}
}
